using System;
using System.Linq;
using System.Collections.Generic;
using Prometheus;
class FixTests0254 {
 static int checks; static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);checks++;Console.WriteLine("PASS "+name);}
 static Clip Clip(string asset,string stream,string track,string name,double at,double len){return new Clip{id=Store.Id(),asset_id=asset,stream_id=stream,track_id=track,name=name,timeline_start=Rational.Frame(at),duration=Rational.Frame(len),source_in=Rational.Frame(0),speed=new Rational(1,1)};}
 static Editor Make(out string track,out string asset,out string stream){var e=new Editor();track=e.Project.Active.tracks.First(t=>t.kind=="video").id;asset=Store.Id();stream=Store.Id();string assetId=asset,streamId=stream;e.Commit(p=>{p.assets.Add(new Asset{id=assetId,name="fixture",locator=new Locator{path="fixture.mp4"},sha256=new string('a',64),presentation_origin=Rational.Time(0),streams=new List<StreamInfo>{new StreamInfo{id=streamId,ordinal=0,kind="video",codec="h264",pts_origin=Rational.Time(0),time_base=new Rational(1,60),duration=Rational.Time(30),nominal_fps=new Rational(60,1)}}});});return e;}
 static void Populate(Editor e,string asset,string stream,string track){e.Commit(p=>{for(int i=0;i<5;i++)p.Active.clips.Add(Clip(asset,stream,track,"C"+i,i*2,2));});}
 static void Main(){string t,a,s;var forward=Make(out t,out a,out s);Populate(forward,a,s,t);string first=forward.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).First().id;forward.InsertSelection(new List<string>{first},first,8,t);var f=forward.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).ToList();Check(f[0].name=="C1"&&f[1].name=="C2"&&f[2].name=="C3"&&f[3].name=="C0"&&f[4].name=="C4","Ctrl drag forward closes source and inserts at requested position");Check(f.Select(c=>c.timeline_start.Seconds).SequenceEqual(new[]{0d,2d,4d,6d,8d}),"forward insert preserves all timeline media without overlaps");
 var backward=Make(out t,out a,out s);Populate(backward,a,s,t);first=backward.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).Last().id;backward.InsertSelection(new List<string>{first},first,0,t);var b=backward.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).ToList();Check(b[0].name=="C4"&&b[1].name=="C0"&&b[2].name=="C1"&&b[3].name=="C2"&&b[4].name=="C3","Ctrl drag backward inserts before existing clips");
 var middle=Make(out t,out a,out s);Populate(middle,a,s,t);first=middle.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).First().id;middle.InsertSelection(new List<string>{first},first,5,t);var m=middle.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).ToList();Store.Validate(middle.Project);Check(m.Any(c=>c.name=="C0"&&c.timeline_start.Seconds==3)&&m.Any(c=>c.name=="C2"&&c.timeline_start.Seconds==2&&Math.Abs(c.duration.Seconds-1)<1e-6)&&m.Any(c=>c.name=="C2"&&c.timeline_start.Seconds==5&&Math.Abs(c.source_in.Seconds-1)<1e-6),"insert into clip splits it and preserves source continuity");
 var ranges=Make(out t,out a,out s);ranges.Commit(p=>p.Active.clips.Add(Clip(a,s,t,"range",0,10)));string rid=ranges.Project.Active.clips[0].id;ranges.RangeTrim(rid,3,5,false);var r=ranges.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).ToList();Store.Validate(ranges.Project);Check(r.Count==2&&r[0].End==3&&r[1].timeline_start.Seconds==5&&r[1].source_in.Seconds==5,"Range Trim keeps both sides and leaves a timeline gap");
 var linked=Make(out t,out a,out s);string audio=Store.Id(),audioStream=Store.Id(),audioTrack=linked.Project.Active.tracks.First(x=>x.kind=="audio").id;linked.Commit(p=>{p.assets[0].streams.Add(new StreamInfo{id=audioStream,ordinal=1,kind="audio",codec="aac",pts_origin=Rational.Time(0),time_base=new Rational(1,48000),duration=Rational.Time(30),sample_rate=48000,channels=2});p.Active.clips.Add(Clip(a,s,t,"Video",0,2));p.Active.clips.Add(Clip(a,audioStream,audioTrack,"Audio",0,2));p.Active.link_groups.Add(new LinkGroup{id=Store.Id(),clip_ids=p.Active.clips.Select(c=>c.id).ToList()});});string videoId=linked.Project.Active.clips.First(c=>c.track_id==t).id;linked.InsertSelection(new List<string>{videoId},videoId,8,t);Check(linked.Project.Active.clips.All(c=>c.timeline_start.Seconds==6)&&linked.Project.Active.link_groups.Count==1,"linked audio video insert moves together");
 var fullLinked=Make(out t,out a,out s);string audioFull=Store.Id(),audioStreamFull=Store.Id(),audioTrackFull=fullLinked.Project.Active.tracks.First(x=>x.kind=="audio").id;fullLinked.Commit(p=>{p.assets[0].streams.Add(new StreamInfo{id=audioStreamFull,ordinal=1,kind="audio",codec="aac",pts_origin=Rational.Time(0),time_base=new Rational(1,48000),duration=Rational.Time(30),sample_rate=48000,channels=2});p.Active.clips.Add(Clip(a,s,t,"Video",0,2));p.Active.clips.Add(Clip(a,audioStreamFull,audioTrackFull,"Audio",0,2));p.Active.link_groups.Add(new LinkGroup{id=Store.Id(),clip_ids=p.Active.clips.Select(c=>c.id).ToList()});});string fullId=fullLinked.Project.Active.clips.First(c=>c.track_id==t).id;fullLinked.RangeTrim(fullId,0,2,false);Check(fullLinked.Project.Active.clips.Count==0&&fullLinked.Project.Active.link_groups.Count==0,"Range Trim can remove a complete linked pair");
 var ripple=Make(out t,out a,out s);Populate(ripple,a,s,t);string rippleId=ripple.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).First().id;string original=ripple.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).Skip(1).First().id;string snapshot=Store.Encode(ripple.Project);ripple.RippleTrim(rippleId,false,1);Check(ripple.Project.Active.clips.Find(c=>c.id==original).timeline_start.Seconds==1,"Ripple Trim right edge moves later content by trimmed duration");ripple.Undo();Check(Store.Encode(ripple.Project)==snapshot,"Ripple Trim is a single atomic undo"); var cross=Make(out t,out a,out s);string targetVideo=Store.Id(),targetAudioTrack=Store.Id(),targetAudioStream=Store.Id();string sourceAudioTrack=cross.Project.Active.tracks.First(x=>x.kind=="audio").id;cross.Commit(p=>{p.assets[0].streams.Add(new StreamInfo{id=targetAudioStream,ordinal=1,kind="audio",codec="aac",pts_origin=Rational.Time(0),time_base=new Rational(1,48000),duration=Rational.Time(30),sample_rate=48000,channels=2});targetVideo=Store.AddTrack(p.Active,"video").id;targetAudioTrack=Store.AddTrack(p.Active,"audio").id;p.Active.clips.Add(Clip(a,s,t,"Video source",0,2));p.Active.clips.Add(Clip(a,s,t,"Video follower",2,2));p.Active.clips.Add(Clip(a,targetAudioStream,sourceAudioTrack,"Audio source",0,2));p.Active.link_groups.Add(new LinkGroup{id=Store.Id(),clip_ids=p.Active.clips.Where(c=>c.timeline_start.Seconds==0).Select(c=>c.id).ToList()});p.Active.clips.Add(Clip(a,s,targetVideo,"Destination",8,2));});string crossVideo=cross.Project.Active.clips.First(c=>c.track_id==t).id;cross.InsertSelection(new List<string>{crossVideo},crossVideo,8,targetVideo);Store.Validate(cross.Project);var movedVideo=cross.Project.Active.clips.Find(c=>c.id==crossVideo);var movedAudio=cross.Project.Active.clips.First(c=>c.timeline_start.Seconds==8&&c.track_id==targetAudioTrack);Check(movedVideo.track_id==targetVideo&&movedAudio.timeline_start.Seconds==8&&cross.Project.Active.clips.Any(c=>c.name=="Destination"&&c.timeline_start.Seconds==10),"forward Insert/Reorder between tracks keeps linked AV aligned and opens destination"); var roll=Make(out t,out a,out s);string leftId=Store.Id(),rightId=Store.Id();roll.Commit(p=>{p.Active.clips.Add(new Clip{id=leftId,name="L",asset_id=a,stream_id=s,track_id=t,timeline_start=Rational.Frame(0),duration=Rational.Frame(2),source_in=Rational.Frame(0),speed=new Rational(1,1)});p.Active.clips.Add(new Clip{id=rightId,name="R",asset_id=a,stream_id=s,track_id=t,timeline_start=Rational.Frame(2),duration=Rational.Frame(2),source_in=Rational.Frame(1),speed=new Rational(1,1)});});roll.RollEdit(leftId,rightId,0);Store.Validate(roll.Project);var rolledLeft=roll.Project.Active.clips.Find(c=>c.id==leftId);var rolledRight=roll.Project.Active.clips.Find(c=>c.id==rightId);Check(rolledLeft.End==1&&rolledRight.timeline_start.Seconds==1&&rolledRight.source_in.Seconds==0&&rolledRight.duration.Seconds==3,"Roll Edit clamps to available source handles"); Console.WriteLine("PASS "+checks+" focused regression checks");}
}





